Writing the error boundary component now.

## Tool: Write

Parameters:
```json
{
  "file_path": "/repo/ErrorBoundary.tsx",
  "content": "import { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary] Caught render error:", error);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    if (!error) return this.props.children;

    if (this.props.fallback) return this.props.fallback(error, this.reset);

    return (
      <div role="alert" style={styles.container}>
        <h2 style={styles.heading}>Something went wrong</h2>
        <pre style={styles.message}>{error.message}</pre>
        <button onClick={this.reset} style={styles.button}>
          Try again
        </button>
      </div>
    );
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "0.5rem",
    background: "#fef2f2",
    color: "#991b1b",
    fontFamily: "sans-serif",
    maxWidth: "40rem",
  },
  heading: { margin: "0 0 0.75rem", fontSize: "1.125rem" },
  message: {
    margin: "0 0 1.25rem",
    fontSize: "0.875rem",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
  },
  button: {
    padding: "0.5rem 1rem",
    background: "#dc2626",
    color: "#fff",
    border: "none",
    borderRadius: "0.375rem",
    cursor: "pointer",
    fontSize: "0.875rem",
  },
};
"
}
```

Done. Here's how to use it:

**Default fallback UI:**
```tsx
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>
```

**Custom fallback:**
```tsx
<ErrorBoundary fallback={(error, reset) => (
  <div>
    <p>Error: {error.message}</p>
    <button onClick={reset}>Retry</button>
  </div>
)}>
  <MyComponent />
</ErrorBoundary>
```

Key details:
- `getDerivedStateFromError` captures the error and triggers the fallback render
- `componentDidCatch` logs the error message and component stack to the console
- The `reset` method clears state, causing children to re-render fresh
- The `fallback` prop is optional — omit it to use the built-in red alert UI with a "Try again" button
